-- Los 35 departamentos del directorio viejo se reemplazan por las direcciones de RRHH (las carga el seed).
-- Solo se borran los que nadie usa: si tienen personas o aplicaciones, administración los cambia y los borra.
DELETE FROM "departments" d WHERE d."rrhh_code" IS NULL AND d."name" IN ('Auditoría Interna', 'Centro Turístico Mi Pueblito', 'Comunicaciones', 'Consejo Municipal', 'Contraloría', 'Cultura', 'Deportes', 'Descentralización', 'Despacho', 'Dirección Administrativa', 'Dirección de Mercados', 'Dirección de Presupuesto', 'Etnias', 'Gestión Ambiental', 'Gestión Social', 'Innovación', 'Legal y Justicia', 'Obras Comunitarias', 'Obras y Construcciones', 'Oficina de Cooperación Internacional', 'Parque Summit', 'Participación Ciudadana', 'Planificación Urbana', 'Proyectos Especiales', 'Recursos Humanos', 'Secretaría de la Mujer', 'Secretaría General', 'Servicios a la Comunidad', 'SIVIMUPA', 'Subdirección de Empresas Municipales', 'Subdirección de Eventos', 'Tecnología', 'Tesorería', 'Trabajo Social', 'Vigilancia Municipal') AND NOT EXISTS (SELECT 1 FROM "users" u WHERE u."department_id" = d."id") AND NOT EXISTS (SELECT 1 FROM "application_departments" a WHERE a."department_id" = d."id");
